template:
% 参数由系统自动注入：\def\radius{3} \def\anglet{270} \def\arcspan{120} \def\angleoffset{120} \def\showtangent{1} \def\showchord{1} \def\showangle{1} \def\showinscribedangle{0} \def\showcentralangle{0} \def\showcenter{1} \def\labelt{T} \def\labela{A} \def\labelc{C}
% 视觉归一化：把直径缩放到 6cm，保证不同半径下图形视觉大小一致。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 三个圆上点的位置角：T 为切点，A = T 沿逆时针转 arcspan，C 再沿逆时针转 angleoffset（落在另一段弧上）
\pgfmathsetmacro{\angA}{\anglet + \arcspan}
\pgfmathsetmacro{\angC}{\anglet + \arcspan + \angleoffset}
\pgfmathsetmacro{\Tx}{\radius*cos(\anglet)}
\pgfmathsetmacro{\Ty}{\radius*sin(\anglet)}
\pgfmathsetmacro{\Ax}{\radius*cos(\angA)}
\pgfmathsetmacro{\Ay}{\radius*sin(\angA)}
\pgfmathsetmacro{\Cx}{\radius*cos(\angC)}
\pgfmathsetmacro{\Cy}{\radius*sin(\angC)}
% 切线方向：垂直于半径 OT，取逆时针切向 anglet+90（该方向与弦 TA 夹出的角所夹弧正好是 T 逆时针到 A 的弧）
\pgfmathsetmacro{\tdx}{cos(\anglet+90)}
\pgfmathsetmacro{\tdy}{sin(\anglet+90)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \draw[thick] (0,0) circle [radius=\radius];
  \ifnum\showtangent>0
    \pgfmathsetmacro{\tlen}{\radius*1.15}
    \draw[thick] ({\Tx - \tlen*\tdx},{\Ty - \tlen*\tdy}) -- ({\Tx + \tlen*\tdx},{\Ty + \tlen*\tdy});
  \fi
  \ifnum\showchord>0
    \draw[thick] ({\Tx},{\Ty}) -- ({\Ax},{\Ay});
  \fi
  % 圆心角 ∠TOA：沿逆时针从 anglet 扫到 angA，与弦切角所夹弧一致（arcspan 可超过 180 度，故显式指定扫描方向）
  \ifnum\showcentralangle>0
    \draw[thick] (0,0) -- ({\Tx},{\Ty});
    \draw[thick] (0,0) -- ({\Ax},{\Ay});
    \pgfmathsetmacro{\carcr}{min(0.5/\figscale, \radius*0.3)}
    \draw[thick] ({\carcr*cos(\anglet)},{\carcr*sin(\anglet)}) arc[start angle=\anglet, end angle=\angA, radius=\carcr];
  \fi
  % 弦切角：顶点 T，两边为切线的逆时针方向与弦 TA
  \ifnum\showangle>0
    \pgfmathsetmacro{\pctax}{\Tx + \radius*\tdx - (\Tx)}
    \pgfmathsetmacro{\pctay}{\Ty + \radius*\tdy - (\Ty)}
    \pgfmathsetmacro{\pctbx}{\Ax - (\Tx)}
    \pgfmathsetmacro{\pctby}{\Ay - (\Ty)}
    \pgfmathsetmacro{\lencta}{sqrt((\pctax)^2 + (\pctay)^2)}
    \pgfmathsetmacro{\lenctb}{sqrt((\pctbx)^2 + (\pctby)^2)}
    \pgfmathsetmacro{\sangct}{atan2(\pctay,\pctax)}
    \pgfmathsetmacro{\erawct}{atan2(\pctby,\pctbx)}
    \pgfmathsetmacro{\edifct}{\erawct - \sangct}
    \pgfmathsetmacro{\eangct}{\sangct + \edifct - 360*round(\edifct/360)}
    \pgfmathsetmacro{\arcrct}{min(0.42/\figscale, \lencta*0.3, \lenctb*0.3)}
    \draw[thick] ({\Tx + \arcrct*cos(\sangct)},{\Ty + \arcrct*sin(\sangct)}) arc[start angle=\sangct, end angle=\eangct, radius=\arcrct];
  \fi
  % 同弧圆周角 ∠TCA（与弦切角相等）
  \ifnum\showinscribedangle>0
    \draw[thick] ({\Cx},{\Cy}) -- ({\Tx},{\Ty});
    \draw[thick] ({\Cx},{\Cy}) -- ({\Ax},{\Ay});
    \pgfmathsetmacro{\pciax}{\Tx - (\Cx)}
    \pgfmathsetmacro{\pciay}{\Ty - (\Cy)}
    \pgfmathsetmacro{\pcibx}{\Ax - (\Cx)}
    \pgfmathsetmacro{\pciby}{\Ay - (\Cy)}
    \pgfmathsetmacro{\lencia}{sqrt((\pciax)^2 + (\pciay)^2)}
    \pgfmathsetmacro{\lencib}{sqrt((\pcibx)^2 + (\pciby)^2)}
    \pgfmathsetmacro{\sangci}{atan2(\pciay,\pciax)}
    \pgfmathsetmacro{\erawci}{atan2(\pciby,\pcibx)}
    \pgfmathsetmacro{\edifci}{\erawci - \sangci}
    \pgfmathsetmacro{\eangci}{\sangci + \edifci - 360*round(\edifci/360)}
    \pgfmathsetmacro{\arcrci}{min(0.42/\figscale, \lencia*0.26, \lencib*0.26)}
    \draw[thick] ({\Cx + \arcrci*cos(\sangci)},{\Cy + \arcrci*sin(\sangci)}) arc[start angle=\sangci, end angle=\eangci, radius=\arcrci];
    \fill ({\Cx},{\Cy}) circle [radius=\dotr pt];
    \node at ({1.16*\radius*cos(\angC)},{1.16*\radius*sin(\angC)}) {$\labelc$};
  \fi
  \ifnum\showcenter>0
    \fill (0,0) circle [radius=\dotr pt];
    \node[above right] at (0,0) {$O$};
  \fi
  \fill ({\Tx},{\Ty}) circle [radius=\dotr pt];
  \node at ({1.16*\radius*cos(\anglet)},{1.16*\radius*sin(\anglet)}) {$\labelt$};
  \fill ({\Ax},{\Ay}) circle [radius=\dotr pt];
  \node at ({1.16*\radius*cos(\angA)},{1.16*\radius*sin(\angA)}) {$\labela$};
\end{tikzpicture}
